[
  {
    "text": "The photographic heritage of Santa Maria is being made accessible in a digital environment using the ICA-AtoM software on the World Wide Web.",
    "topic": "digital preservation of photographic heritage"
  },
  {
    "text": "The access to the photographic archive of the Historical Municipal Archive of Santa Maria is discussed based on archival theoretical criteria for description and access.",
    "topic": "archival criteria for digital access"
  },
  {
    "text": "ICA-AtoM (International Council on Archives Access to Memory) software is being utilized to facilitate the digital access to the Santa Maria photographic archive.",
    "topic": "use of ICA-AtoM for archival access"
  },
  {
    "text": "The digital access to the Santa Maria photographic archive aims to meet theoretical archival standards for description and access.",
    "topic": "theoretical standards for digital archival access"
  },
  {
    "text": "The research focuses on the potential of information and communication technologies to enhance access to the Santa Maria photographic heritage.",
    "topic": "information and communication technologies for heritage access"
  }
]
